// ============================================================
//  MONTAR LOTES — PARES (mesmo setor, andam juntos)
//  >>> COLE SEU TOKEN DA BRAPI na linha TOKEN abaixo <<<
//  Modo do node: "Run Once for All Items"
// ============================================================

const TOKEN = 'COLE_SEU_TOKEN_AQUI';     // <<< troque aqui
const RANGE = '3mo';
const INTERVAL = '1d';

// Pares da B3 do mesmo setor (tendem a andar juntos).
// Edite à vontade: [ativoA, ativoB, 'nome do setor']
const PARES = [
  ['ITUB4','BBDC4','Bancos'],
  ['PETR4','PRIO3','Petróleo'],
  ['VALE3','CSNA3','Mineração/Siderurgia'],
  ['ABEV3','CRFB3','Consumo'],
  ['BBAS3','SANB11','Bancos 2'],
  ['GGBR4','GOAU4','Siderurgia'],
  ['ELET3','CMIG4','Energia'],
  ['CYRE3','MRVE3','Construção']
];

// junta todos os tickers únicos dos pares (1 requisição por ticker no plano grátis)
const unicos = [];
for (const [a,b] of PARES) { if(!unicos.includes(a)) unicos.push(a); if(!unicos.includes(b)) unicos.push(b); }

const lotes = [];
for (const t of unicos) {
  lotes.push({ json: {
    url: 'https://brapi.dev/api/quote/' + encodeURIComponent(t) + '?range=' + RANGE + '&interval=' + INTERVAL + '&token=' + TOKEN,
    lote: t
  }});
}
return lotes;

// ============================================================
//  PAIRS TRADING v4 — BLOCO ÚNICO + qualidade do sinal (distância moderada = melhor)
//  Este único nó busca os ativos (devagar, p/ não tomar corte
//  da brapi) e calcula os pares. Substitui "Montar Lotes",
//  "Buscar Candles" E o cérebro — é tudo aqui.
//
//  COMO USAR:
//   - Fluxo: [Clicar para Testar] -> [ESTE nó] -> [Gerar Excel]
//   - Cole SEU TOKEN da brapi na linha TOKEN abaixo.
//   - Modo do nó: "Run Once for All Items"
// ============================================================

// ---------- AJUSTES ----------
const TOKEN = 'COLE_SEU_TOKEN_AQUI';   // <<< troque aqui
const RANGE = '3mo';
const PAUSA_MS = 350;      // pausa entre cada busca (evita corte por velocidade)
const JANELA = 60;         // dias p/ a "distância normal" do par
const Z_ENTRADA = 2.0;     // esticou 2 desvios = sinal
const Z_FORTE = 2.5;

const PARES = [
  // Bancos
  ['ITUB4','BBDC4','Bancos'],
  ['BBAS3','SANB11','Bancos 2'],
  ['ITUB4','BBAS3','Bancos 3'],
  // Petróleo / combustível
  ['PETR4','PRIO3','Petróleo'],
  ['PETR3','PETR4','Petrobras ON/PN'],
  ['VBBR3','UGPA3','Distribuição comb.'],
  // Mineração / siderurgia
  ['VALE3','CSNA3','Mineração/Sider.'],
  ['GGBR4','GOAU4','Siderurgia'],
  ['CSNA3','GGBR4','Siderurgia 2'],
  ['CMIN3','VALE3','Mineração 2'],
  // Energia elétrica
  ['ELET3','CMIG4','Energia'],
  ['EQTL3','ENGI11','Energia 2'],
  ['CPFE3','CMIG4','Energia 3'],
  // Construção / shoppings
  ['CYRE3','MRVE3','Construção'],
  ['EZTC3','CYRE3','Construção 2'],
  ['MULT3','IGTI11','Shoppings'],
  // Proteína / consumo
  ['JBSS3','BEEF3','Frigoríficos'],
  // Varejo
  ['LREN3','GMAT3','Varejo'],
  ['RADL3','RAIZ4','Farmácia/Energia'],
  // Papel / celulose
  ['SUZB3','KLBN11','Papel/Celulose'],
  // Bolsa / seguros
  ['B3SA3','BPAC11','Financeiro'],
  ['BBSE3','PSSA3','Seguros'],
  ['WEGE3','EMBR3','Industrial'],
  ['RENT3','VAMO3','Locação']
];
// -----------------------------

// 1) lista de tickers únicos
const unicos = [];
for (const [a,b] of PARES) { if(!unicos.includes(a)) unicos.push(a); if(!unicos.includes(b)) unicos.push(b); }

// 2) buscar cada um, com pausa entre as buscas
const porSimbolo = {};
const erros = [];
for (const t of unicos) {
  const url = 'https://brapi.dev/api/quote/' + encodeURIComponent(t) + '?range=' + RANGE + '&interval=1d&token=' + TOKEN;
  try {
    const resp = await this.helpers.httpRequest({ method: 'GET', url: url, json: true });
    const r = (resp && resp.results && resp.results[0]) ? resp.results[0] : null;
    const candles = r && r.historicalDataPrice ? r.historicalDataPrice : [];
    porSimbolo[t] = candles
      .filter(c => c && typeof c.close === 'number' && c.date)
      .sort((x,y)=>x.date-y.date);
  } catch (e) {
    porSimbolo[t] = [];
    erros.push(t);
  }
  await new Promise(res => setTimeout(res, PAUSA_MS));
}

// 3) calcular os pares
function alinhar(cA, cB) {
  const mapB = {}; for (const c of cB) mapB[c.date] = c.close;
  const ra = [], rb = [];
  for (const c of cA) if (mapB[c.date] !== undefined) { ra.push(c.close); rb.push(mapB[c.date]); }
  return { a: ra, b: rb };
}

const saida = [];
for (const [simA, simB, setor] of PARES) {
  const cA = porSimbolo[simA] || [], cB = porSimbolo[simB] || [];
  if (cA.length < 20 || cB.length < 20) {
    const faltou = [];
    if (cA.length < 20) faltou.push(simA + ' (' + cA.length + ')');
    if (cB.length < 20) faltou.push(simB + ' (' + cB.length + ')');
    saida.push({ json: { par: simA+' / '+simB, setor, status:'DADOS INSUFICIENTES', zscore:null, temSinal:'nao',
      resumo: simA+' / '+simB+': faltou histórico -> ' + faltou.join(' e ') } });
    continue;
  }
  const al = alinhar(cA, cB);
  if (al.a.length < 20) {
    saida.push({ json: { par: simA+' / '+simB, setor, status:'POUCAS DATAS EM COMUM', zscore:null, temSinal:'nao',
      resumo: simA+' / '+simB+': poucas datas coincidentes ('+al.a.length+').' } });
    continue;
  }

  const razao = al.a.map((v,i)=> v / al.b[i]);
  const jan = razao.slice(-JANELA);
  const media = jan.reduce((s,x)=>s+x,0)/jan.length;
  let varc = 0; for (const x of jan) varc += (x-media)*(x-media);
  const desvio = Math.sqrt(varc/jan.length);
  const razaoHoje = razao[razao.length-1];
  const z = desvio>0 ? (razaoHoje-media)/desvio : 0;
  const precoA = al.a[al.a.length-1], precoB = al.b[al.b.length-1];
  const absЗ = Math.abs(z);

  let sinal='NEUTRO (dentro do normal)', comprar='-', vender='-', forca='-';
  if (absЗ >= Z_ENTRADA) {
    forca = absЗ >= Z_FORTE ? 'FORTE' : 'moderado';
    if (z > 0) { comprar = simB; vender = simA; sinal = simA+' cara vs '+simB; }
    else { comprar = simA; vender = simB; sinal = simB+' cara vs '+simA; }
  }
  const distPct = media>0 ? ((razaoHoje-media)/media)*100 : 0;
  const temSinal = absЗ >= Z_ENTRADA;

  // qualidade do sinal: distância MODERADA reverte; distância ENORME = provável quebra de correlação
  let qualidade = '-';
  if (temSinal) {
    const ad = Math.abs(distPct);
    if (ad <= 12) qualidade = 'BOM (dist. moderada, tende a reverter)';
    else if (ad <= 20) qualidade = 'ATENCAO (dist. alta)';
    else qualidade = 'EVITAR (dist. enorme = correlação pode ter quebrado)';
  }

  saida.push({ json: {
    par: simA+' / '+simB, setor,
    zscore: Number(z.toFixed(2)),
    temSinal: temSinal ? 'SIM' : 'nao',
    forcaSinal: temSinal ? forca : '-',
    qualidade: qualidade,
    sinal, comprar, vender,
    precoA: Number(precoA.toFixed(2)),
    precoB: Number(precoB.toFixed(2)),
    distanciaPct: Number(distPct.toFixed(1)),
    resumo: (temSinal ? '[SINAL '+forca+'] ' : '[sem sinal] ') + setor + ': ' + simA+'/'+simB +
            ' | z=' + z.toFixed(2) + (temSinal ? ' | COMPRAR '+comprar+' + VENDER '+vender : '') +
            ' | dist ' + distPct.toFixed(1) + '%' + (temSinal ? ' | ' + qualidade : '')
  }});
}

saida.sort((a,b)=> Math.abs(b.json.zscore||0) - Math.abs(a.json.zscore||0));
return saida;

// ============================================================
//  ATUALIZAR MEMÓRIA — junta o histórico já salvo (CSV) com os
//  candles novos da rodada de hoje, sem duplicar datas.
//  Entrada (input): linhas do CSV antigo (vindas do "Extrair CSV").
//  Também lê os candles do node "Buscar Candles (brapi)".
//  Modo do node: "Run Once for All Items"
// ============================================================

const mapa = new Map(); // chave: TICKER|DATA  ->  {ticker, date, close}

// 1) carregar o histórico que já existe no CSV
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ticker && j.date) {
    mapa.set(j.ticker + '|' + j.date, {
      ticker: String(j.ticker),
      date: String(j.date),
      close: Number(j.close)
    });
  }
}

// 2) acrescentar os candles novos vindos da brapi
const lotes = $('Buscar Candles (brapi)').all();
for (const it of lotes) {
  const results = (it.json && it.json.results) || [];
  for (const ativo of results) {
    const sym = ativo.symbol;
    if (!sym) continue;
    const candles = ativo.historicalDataPrice || [];
    for (const c of candles) {
      if (!c || typeof c.close !== 'number' || !c.date) continue;
      const d = new Date(c.date * 1000).toISOString().slice(0, 10); // AAAA-MM-DD
      mapa.set(sym + '|' + d, { ticker: sym, date: d, close: c.close });
    }
  }
}

// 3) devolver tudo ordenado (ticker, depois data)
const linhas = Array.from(mapa.values())
  .sort((a, b) => a.ticker.localeCompare(b.ticker) || a.date.localeCompare(b.date));

return linhas.map(l => ({ json: l }));
